import React, { useState } from 'react';

// Create the StarRating component here
const StarRating = () => {
  // Initialize rating state here
  const [rating, setRating] = useState(0);

  // Initialize hover state here
  const [hover, setHover] = useState(0);

  // Create handleMouseEnter function here
  const handleMouseEnter = (index) => {
    setHover(index);
  };

  // Create handleMouseLeave function here
  const handleMouseLeave = () => {
    setHover(0);
  };

  // Create handleClick function here
  const handleClick = (index) => {
    setRating(index);
  };

  return (
    <div>
      {/* Add 5 star buttons here */}
      {[1, 2, 3, 4, 5].map((index) => (
        <button
          key={index}
          onMouseEnter={() => handleMouseEnter(index)}
          onMouseLeave={handleMouseLeave}
          onClick={() => handleClick(index)}
        >
          {/* Add conditional star display logic here */}
        </button>
      ))}
    </div>
  );
};
